const STY = (bg, w, h, l, t) => `position:absolute;left:${l}px;top:${t}px;width:${w}px;height:${h}px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.4);background:${bg};color:#ffffff;font-weight:800;line-height:1.1;opacity:0;transform-origin:center;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.2">
    <path id="l0" d="M470 530 L240 160" />
    <path id="l1" d="M470 530 L700 160" />
    <path id="l2" d="M470 530 L240 900" />
    <path id="l3" d="M470 530 L700 900" />
  </svg>
  <div id="c4" style="${STY(B1, 440, 180, 250, 440)};font-size:52px;">DATA<br>CENTERS</div>
  <div id="c0" style="${STY(B2, 400, 140, 40, 90)};font-size:42px;">NEW<br>BRANDING</div>
  <div id="c1" style="${STY(B2, 400, 140, 500, 90)};font-size:42px;">POWER<br>LIMITS</div>
  <div id="c2" style="${STY(B2, 400, 140, 40, 830)};font-size:42px;">WATER<br>USAGE</div>
  <div id="c3" style="${STY(B2, 400, 140, 500, 830)};font-size:42px;">PHYSICAL<br>SCALE</div>
`;

const cards = [0, 1, 2, 3, 4].map(i => root.querySelector('#c' + i));
const lines = [0, 1, 2, 3].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const st = Math.min(t, d * 0.55);

  // Hub Card (index 4)
  const sH = spr(st, 0.1, 0.85, 8);
  cards[4].style.opacity = clamp(sH * 1.5);
  cards[4].style.transform = `scale(${lerp(0.7, 1, clamp(sH))})`;

  // Lines growth
  lines.forEach((line, i) => {
    const sL = spr(st, 0.6 + i * 0.1, 0.9, 10);
    line.el.style.strokeDashoffset = lerp(line.len, 0, clamp(sL));
    line.el.style.opacity = lerp(0, 0.4, clamp(sL));
  });

  // Outer Cards
  [0, 1, 2, 3].forEach(i => {
    const sC = spr(st, 1.2 + i * 0.2, 0.8, 7);
    cards[i].style.opacity = clamp(sC * 1.2);
    const yOff = lerp(30, 0, E_OUT(clamp(sC)));
    const scale = lerp(0.85, 1, clamp(sC));
    // Positions are fixed, so we just translate for the slide-in effect
    cards[i].style.transform = `translateY(${i < 2 ? -yOff : yOff}px) scale(${scale})`;
  });
}
